def get_string_stats(strings):
    """返回每个字符串的长度列表，以及最大长度和总长度。"""
    lengths = [len(s) for s in strings]
    max_length = max(lengths) if lengths else 0  # 统计最大长度
    total_length = sum(lengths)  # 统计总长度
    return lengths, max_length, total_length


# 统计字符串长度、最大长度和总长度
lengths, max_length, total_length = get_string_stats(input)

# 输出结果
for string, length in zip(input, lengths):
    print(f"'{string}' 的长度是: {length}")

print(f"最大长度是: {max_length}")
print(f"总长度是: {total_length}")

